W("Read-only check of Windows-era scripts, jobs, hooks and paths left on the Mac and on GitHub. 6 auditors (one area each) and 1 skeptic who re-checked all 70 port/delete calls. Yesterday's findings (`2026-10-22-system-audit-findings.md`) are cited by id, not repeated.\n\n")
W(f"**Totals:** {len(rows)} items. Final calls: " + ", ".join(f"{k} {v}" for k,v in c.most_common()) + ".\n\n")
W("**Already settled by the scout:** all 160 erash11 GitHub repos are cloned on the Mac; no repo has Windows CI or scheduled Actions. Of the 18 Windows scheduled tasks, 10 have working Mac coverage, 2 were retired by Eric, 2 only make sense on Windows, 2 are dead code, 2 run nowhere (DailyGmailDigest, nightly-digest). Env vars from the handoff: PFF_DB, CLAUDE_CODE_PLUGIN_DIRS, FIREFLIES_API_KEY, TYPESAFE_API_KEY set; GITHUB_PERSONAL_ACCESS_TOKEN, CODEX_GITHUB_PERSONAL_ACCESS_TOKEN, GMAIL_APP_PASSWORD, GOPATH, RENV_PATHS_LIBRARY_ROOT unset (no live job needs them; GitHub MCP is finding disksec-github-mcp-env-missing). WSL home on the laptop was never checked and cannot be from here.\n\n")
for want,title in [('port','Port or fix (final call: port)'),('delete','Delete (final call: delete)'),('keep','Keep'),('already-done','Already done')]:
    sel=[x for x in rows if x[2]==want]
    W(f"## {title} — {len(sel)}\n\n| id | item | Mac status | effort | in-season | known finding | skeptic |\n|---|---|---|---|---|---|---|\n")
    for a,k,f,it,s in sel:
        W(f"| {a}#{k} | {it['name'].replace('|','/')} | {it['mac_status']} | {it['effort']} | {'yes' if it['mid_season_risk'] else ''} | {it['finding_id_if_known'] or ''} | {s.get('verdict','')} |\n")
    W("\n")
W("## Item detail\n\n")
for a,k,f,it,s in rows:
    W(f"### {a}#{k} — {it['name']}  → **{f}**\n\n")
    for key in ['location','what_it_does','windows_origin','referenced_by','evidence','value']:
        if it.get(key): W(f"- **{key}:** {it[key]}\n")
    if s: W(f"- **skeptic ({s['verdict']} → {s['corrected_recommendation']}):** {s['reason']}\n")
    W("\n")
W("## Not checked\n\n")
for r in d['reports']:
    for n in r['not_checked']: W(f"- ({r['area']}) {n}\n")
EOF
python3 $S/mkreport.py $S/audit.json ~/.claude/audits/2026-10-23-windows-holdover-audit.md && wc -c ~/.claude/audits/2026-10-23-windows-holdover-audit.md && cp $S/audit.json ~/.claude/audits/2026-10-23-windows-holdover-audit.json

